vrml.10:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

Background {
  skyColor 0.12 0.14 0.2
}

NavigationInfo {
  type "EXAMINE"
  transitionType "TELEPORT"
}

DEF O1 OrthoViewpoint {
  fieldOfView -4 -4 4 4
}

DEF SW Switch {
  whichChoice 0
  children DEF GS Transform {
    scale 1.2 1 1
    children [
      Transform {
        translation -1.5 0 0
        children Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.3 0.5 0.9
            }
          }
          geometry Box {
            size 1.5 1.5 1.5
          }
        }
      }
      Transform {
        translation 1.5 0 0
        children Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.9 0.6 0.2
            }
          }
          geometry Sphere {
            radius 0.9
          }
        }
      }
      DEF FAR Transform {
        translation 0 2.5 -2
        children Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.4 0.9 0.4
            }
          }
          geometry Box {
            size 1 1 1
          }
        }
      }
    ]
  }
}

DEF K KeySensor { }

DEF R Script {
  inputOnly      SFString on_key
  inputOutput    SFString log ""
  initializeOnly SFNode   o1 USE O1

  url "javascript:
function on_key (k)
{
   log = log + 'K' + k + ' ';
   if (k == 'a') o1 .viewAll = true;
}
"
  directOutput TRUE
}

ROUTE K.keyPress TO R.on_key

